<?php
require_once '../includes/security.php';start_secure_session();require_roles(['admin']);require_csrf();require '../includes/db.php';require 'audit.php';$s=$_SESSION['case_import_preview']??null;if(!$s||!hash_equals($s['token'],(string)($_POST['preview_token']??''))||time()-$s['created']>3600){header('Location: ../auth/admin/cases/import.php?error=preview_expired');exit;}$p=$s['preview'];$uid=(int)$_SESSION['user_id'];$summary=json_encode(['total'=>$p['total'],'valid'=>$p['valid'],'warning'=>$p['warning'],'invalid'=>$p['invalid'],'duplicates'=>$p['duplicates']]);$stmt=$conn->prepare("INSERT INTO import_batches(source_type,source_name,source_hash,status,validation_summary,created_by,started_at)VALUES('case_document',?,?,'validated',?,?,NOW())");$stmt->bind_param('sssi',$s['name'],$s['hash'],$summary,$uid);try{$stmt->execute();}catch(mysqli_sql_exception$e){header('Location: ../auth/admin/cases/import.php?error=duplicate_file');exit;}$batch=$conn->insert_id;$imported=0;$skipped=0;try{$conn->begin_transaction();$conn->query("UPDATE import_batches SET status='importing' WHERE id=$batch");foreach($p['rows']as$row){if($row['status']==='invalid'){$skipped++;continue;}$x=$row['case'];$assigned=$x['case_type']==='land_dispute'?'assessor':'tribe_leader';$stmt=$conn->prepare("INSERT INTO case_applications(applicant_fullname,applicant_gender,applicant_dob,applicant_contact,applicant_email,applicant_address,applicant_ip_group,applicant_affiliation_id,rep_name,rep_relationship,rep_contact,case_title,case_type,case_type_id,incident_date,incident_location_text,case_description,status,created_by,assigned_to)VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'pending',?,?)");$stmt->bind_param('sssssssissssiisssis',$x['applicant_fullname'],$x['applicant_gender'],$x['applicant_dob'],$x['applicant_contact'],$x['applicant_email'],$x['applicant_address'],$s['ownership'],$x['applicant_affiliation_id'],$x['rep_name'],$x['rep_relationship'],$x['rep_contact'],$x['case_title'],$x['case_type'],$x['case_type_id'],$x['incident_date'],$x['incident_location_text'],$x['case_description'],$uid,$assigned);$stmt->execute();$cid=$conn->insert_id;foreach($row['participants']as$person){$relationship=$person['relationship']??null;$contact=$person['contact']??null;$stmt=$conn->prepare('INSERT INTO case_persons_involved(case_id,person_name,role,relationship_to_applicant,contact)VALUES(?,?,?,?,?)');$stmt->bind_param('issss',$cid,$person['name'],$person['role'],$relationship,$contact);$stmt->execute();}$imported++;}$final=json_encode(['imported'=>$imported,'skipped'=>$skipped]);$stmt=$conn->prepare("UPDATE import_batches SET status='completed',validation_summary=?,completed_at=NOW() WHERE id=?");$stmt->bind_param('si',$final,$batch);$stmt->execute();$conn->commit();log_action($conn,'IMPORT_CASES','import_batches',$batch,"Completed case import batch; imported=$imported; skipped=$skipped");@unlink($s['path']);unset($_SESSION['case_import_preview']);header("Location: ../auth/admin/cases/import.php?completed=$batch");}catch(Throwable$e){$conn->rollback();$safe='{"error":"Case import failed; no case rows committed."}';$stmt=$conn->prepare("UPDATE import_batches SET status='failed',validation_summary=?,completed_at=NOW() WHERE id=?");$stmt->bind_param('si',$safe,$batch);$stmt->execute();error_log('Case import failed: '.$e->getMessage());header('Location: ../auth/admin/cases/import.php?error=import_failed');}
